(2154624, 294574, 10858, '<td valign="top">A good idea, which could be improved technically. The wrappings of the background are distracting a bit, I would iron it and would not place the bottle to the side, I would put it a little bit more to the left, no matter if the glass covers a part of it. Holding the hand absolutely vertical would make your decision more confident, IMO.</td>', 'A good idea, which could be improved technically. The wrappings of the background are distracting a bit, I would iron it and would not place the bottle to the side, I would put it a little bit more to the left, no matter if the glass covers a part of it. Holding the hand absolutely vertical would make your decision more confident, IMO.', '2006-02-15 17:23:22.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(2154629, 295247, 9083, '<td valign="top">Cool!  Ingenious 8</td>', 'Cool!  Ingenious 8', '2006-02-15 17:24:54.000000', NULL, 1),
(2154630, 295219, 10858, '<td valign="top">The candlelight is overexposed and Bible has a harsh shadow. Otherwise the idea is nice, try some other compositions, angles to enhance the interest for your photo.</td>', 'The candlelight is overexposed and Bible has a harsh shadow. Otherwise the idea is nice, try some other compositions, angles to enhance the interest for your photo.', '2006-02-15 17:24:56.000000', NULL, 1),
(2154632, 295298, 9083, '<td valign="top">Oh dear, what happened to the colour?</td>', 'Oh dear, what happened to the colour?', '2006-02-15 17:25:28.000000', NULL, 1),
(2154636, 295742, 10858, '<td valign="top">There are a lot of church entries, what I like here is that you got inside. Good composition, though it seems grainy.</td>', 'There are a lot of church entries, what I like here is that you got inside. Good composition, though it seems grainy.', '2006-02-15 17:25:53.000000', NULL, 1),
(2154641, 293336, 10858, '<td valign="top">Not easy to take photos of insects, they are quick. Some colour balance would help here, the bee looks a bit greenish, and focus should be more spot on.</td>', 'Not easy to take photos of insects, they are quick. Some colour balance would help here, the bee looks a bit greenish, and focus should be more spot on.', '2006-02-15 17:27:09.000000', NULL, 1),
(2154642, 294289, 9083, '<td valign="top">A tighter crop may have enhanced the overall image?</td>', 'A tighter crop may have enhanced the overall image?', '2006-02-15 17:27:25.000000', NULL, 1),
(2154651, 295142, 10858, '<td valign="top">Difficult to take good shots of metal. Here I would use a darker background. Lighting is good, but could be improved to avoid the shadows in the front. On a black or grey background it wouldn''t be a problem.</td>', 'Difficult to take good shots of metal. Here I would use a darker background. Lighting is good, but could be improved to avoid the shadows in the front. On a black or grey background it wouldn''t be a problem.', '2006-02-15 17:28:38.000000', NULL, 1),
(2154654, 294580, 9083, '<td valign="top">Nice composition</td>', 'Nice composition', '2006-02-15 17:29:12.000000', NULL, 1),
(2154657, 294617, 10858, '<td valign="top">It''s a pity the front of the church is in shadow, what about trying another period of the day? The tilting is strange for me, I don''t understand the reason.</td>', 'It''s a pity the front of the church is in shadow, what about trying another period of the day? The tilting is strange for me, I don''t understand the reason.', '2006-02-15 17:30:02.000000', NULL, 1),
(2154658, 295165, 9083, '<td valign="top">Let me guess.......Lots of superglue?</td>', 'Let me guess.......Lots of superglue?', '2006-02-15 17:30:18.000000', NULL, 1),
(2154663, 295311, 10858, '<td valign="top">Good composition, this made me smile. :-) Well, it''s not a stunning one, but it''s nice.</td>', 'Good composition, this made me smile. :-) Well, it''s not a stunning one, but it''s nice.', '2006-02-15 17:31:49.000000', NULL, 1),
(2154669, 295314, 10858, '<td valign="top">Good composition of these Valentine-day girls. However, I can''t really find the relationship with Charity.</td>', 'Good composition of these Valentine-day girls. However, I can''t really find the relationship with Charity.', '2006-02-15 17:34:19.000000', NULL, 1),
(2154675, 295524, 10858, '<td valign="top">This one would be OK for diligence, too, it''s an unique one. I like the composition, but because of the lighting (flash?) there are some strong shadows which would be better to avoid.</td>', 'This one would be OK for diligence, too, it''s an unique one. I like the composition, but because of the lighting (flash?) there are some strong shadows which would be better to avoid.', '2006-02-15 17:36:16.000000', NULL, 1),
(2154682, 295558, 10858, '<td valign="top">The colour tones and her look touched me. I like the noble way she is interpreting her faith. Among my top 3 choices for this one!<br/> <br/>Edit: some spell mistakes and I was looking for the right word. I just can''t find words I love this photo! :-)</td>', 'The colour tones and her look touched me. I like the noble way she is interpreting her faith. Among my top 3 choices for this one! Edit: some spell mistakes and I was looking for the right word. I just can''t find words I love this photo! :-)', '2006-02-15 17:38:58.000000', NULL, 1),
(2154689, 295578, 10858, '<td valign="top">Sweetie!!! Adorable expression on the face, great composition and soft skin. I am not sure whether the sunlight on her hair enhances the shot, though.<br/> <br/>Edit: Sorry, I was looking for the right expression.</td>', 'Sweetie!!! Adorable expression on the face, great composition and soft skin. I am not sure whether the sunlight on her hair enhances the shot, though. Edit: Sorry, I was looking for the right expression.', '2006-02-15 17:40:13.000000', NULL, 1),
