(2160677, 295900, 37879, '<td valign="top">too dark for me to tell what this is</td>', 'too dark for me to tell what this is', '2006-02-18 07:08:54.000000', NULL, 1),
(2160678, 295456, 37879, '<td valign="top">not crazy about the special effect</td>', 'not crazy about the special effect', '2006-02-18 07:09:17.000000', NULL, 1),
