(2161933, 295609, 30982, '<td valign="top">Looks darn cold!  Not sure of the virtue link, but the picture is definitely crisp and I like the leading line and the steam against the sky.  Not sure what the red things are.  The closest one almost looks like someone''s undies frozen to a chain!</td>', 'Looks darn cold!  Not sure of the virtue link, but the picture is definitely crisp and I like the leading line and the steam against the sky.  Not sure what the red things are.  The closest one almost looks like someone''s undies frozen to a chain!', '2006-02-18 19:56:05.000000', NULL, 1),
(2161934, 294388, 53243, '<td valign="top">very unsual, and beautiful macro</td>', 'very unsual, and beautiful macro', '2006-02-18 19:56:17.000000', NULL, 1),
(2161935, 295695, 30982, '<td valign="top">Interesting interpretation - fits the challenge.  Overall kind of "flat" and leave you wondering what the other cuff is attached to.</td>', 'Interesting interpretation - fits the challenge.  Overall kind of "flat" and leave you wondering what the other cuff is attached to.', '2006-02-18 19:57:15.000000', NULL, 1),
(2161936, 295616, 53243, '<td valign="top">brave or a good friend</td>', 'brave or a good friend', '2006-02-18 19:57:29.000000', NULL, 1),
(2161937, 295180, 30982, '<td valign="top">Nice use of the sky and clouds to frame the subject.</td>', 'Nice use of the sky and clouds to frame the subject.', '2006-02-18 19:58:10.000000', NULL, 1),
(2161938, 295546, 53243, '<td valign="top">wonderful and so authentic to tradition</td>', 'wonderful and so authentic to tradition', '2006-02-18 19:58:25.000000', NULL, 1),
(2161939, 295277, 53243, '<td valign="top">thanks for the compassion and for sharing the real meaning of life</td>', 'thanks for the compassion and for sharing the real meaning of life', '2006-02-18 19:59:41.000000', NULL, 1),
(2161940, 295298, 30982, '<td valign="top">Without the title, I don''t see a "virtue".  With the title, OK, but tenuous.  The grain in the background doesn''t add to this picture - it''s too strong.  And for some reason, the tips of the fingers appear transparent.</td>', 'Without the title, I don''t see a "virtue".  With the title, OK, but tenuous.  The grain in the background doesn''t add to this picture - it''s too strong.  And for some reason, the tips of the fingers appear transparent.', '2006-02-18 20:00:03.000000', NULL, 1),
(2161942, 294408, 53243, '<td valign="top">what a  beautiful view of the clouds</td>', 'what a  beautiful view of the clouds', '2006-02-18 20:01:19.000000', NULL, 1),
(2161944, 295600, 30982, '<td valign="top">The link to the challenge isn''t readily apparent without the title, but the composition of the picture is nice with the two trees forming natural frames on the sides.  Like the people underneath the right side as well.</td>', 'The link to the challenge isn''t readily apparent without the title, but the composition of the picture is nice with the two trees forming natural frames on the sides.  Like the people underneath the right side as well.', '2006-02-18 20:02:34.000000', NULL, 1),
(2161945, 295901, 53243, '<td valign="top">thanks for the reminder</td>', 'thanks for the reminder', '2006-02-18 20:02:34.000000', NULL, 1),
(2161946, 295697, 30982, '<td valign="top">Lovely winter scene - may have cropped to get rid of the camper on the right though that puts the main structure too close to the edge, I suppose.</td>', 'Lovely winter scene - may have cropped to get rid of the camper on the right though that puts the main structure too close to the edge, I suppose.', '2006-02-18 20:03:47.000000', NULL, 1),
(2161947, 294287, 30982, '<td valign="top">Nicely lit.</td>', 'Nicely lit.', '2006-02-18 20:04:06.000000', NULL, 1),
(2161948, 295868, 30982, '<td valign="top">This would have fit nicely in the heart challenge.</td>', 'This would have fit nicely in the heart challenge.', '2006-02-18 20:04:35.000000', NULL, 1),
(2161949, 295038, 30982, '<td valign="top">The fan just seems so incongruous with the architecture, doesn''t it?</td>', 'The fan just seems so incongruous with the architecture, doesn''t it?', '2006-02-18 20:05:39.000000', NULL, 1),
(2161951, 295247, 30982, '<td valign="top">Heh!  Clever interpretation and well executed.</td>', 'Heh!  Clever interpretation and well executed.', '2006-02-18 20:06:13.000000', NULL, 1),
(2161953, 295578, 30982, '<td valign="top">Lovely - the quilt and bedframe add to the simple innocence of the picture.</td>', 'Lovely - the quilt and bedframe add to the simple innocence of the picture.', '2006-02-18 20:07:05.000000', NULL, 1),
(2161954, 295332, 30982, '<td valign="top">Simple and quietly elegant.</td>', 'Simple and quietly elegant.', '2006-02-18 20:07:30.000000', NULL, 1),
(2161960, 293524, 30982, '<td valign="top">Looks like a beautiful place!  A bit of flare from the sun and the trees lack a bit of sharpness to define them fully against the sky.</td>', 'Looks like a beautiful place!  A bit of flare from the sun and the trees lack a bit of sharpness to define them fully against the sky.', '2006-02-18 20:11:13.000000', NULL, 1),
(2161962, 295360, 30982, '<td valign="top">Works well in black and white.  Perhaps a more "head" on shot?  :-)</td>', 'Works well in black and white.  Perhaps a more "head" on shot?  :-)', '2006-02-18 20:12:46.000000', NULL, 1),
(2161963, 295755, 30982, '<td valign="top">The expression of the girl on the right seems out of place compared to the rest, particularly the young man sitting next to her.  Maybe that''s what makes this work so well.</td>', 'The expression of the girl on the right seems out of place compared to the rest, particularly the young man sitting next to her.  Maybe that''s what makes this work so well.', '2006-02-18 20:14:03.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(2161964, 295277, 30982, '<td valign="top">Excellent subject choice but there''s some odd flare/blur over the gentleman''s head and I''d love to see the focus a little sharper.  Great expressions on both, though.</td>', 'Excellent subject choice but there''s some odd flare/blur over the gentleman''s head and I''d love to see the focus a little sharper.  Great expressions on both, though.', '2006-02-18 20:15:02.000000', NULL, 1),
(2161965, 294517, 30982, '<td valign="top">Simple and nice.  Like the use of the headstone in the foreground.</td>', 'Simple and nice.  Like the use of the headstone in the foreground.', '2006-02-18 20:15:27.000000', NULL, 1),
(2161966, 295529, 30982, '<td valign="top">The blues give this a restful feel.</td>', 'The blues give this a restful feel.', '2006-02-18 20:16:02.000000', NULL, 1),
(2161969, 295519, 30982, '<td valign="top">Good closeup work but a bit of a stretch for the challenge.</td>', 'Good closeup work but a bit of a stretch for the challenge.', '2006-02-18 20:16:56.000000', NULL, 1),
