(2161977, 295544, 30982, '<td valign="top">Interesting choice of subject!  Nice execution.</td>', 'Interesting choice of subject!  Nice execution.', '2006-02-18 20:19:36.000000', NULL, 1),
(2161979, 293215, 30982, '<td valign="top">I like this one quite a bit.</td>', 'I like this one quite a bit.', '2006-02-18 20:20:15.000000', NULL, 1),
