(2161982, 295189, 30982, '<td valign="top">Not sure what the link to "charity" is here.  Use the full size allowed for your picture (640 pixels on the longest side) so it can be seen more clearly.</td>', 'Not sure what the link to "charity" is here.  Use the full size allowed for your picture (640 pixels on the longest side) so it can be seen more clearly.', '2006-02-18 20:22:23.000000', NULL, 1),
(2161984, 295367, 30982, '<td valign="top">A good idea for the challenge - hard to get the subject to stand out in such a setting.</td>', 'A good idea for the challenge - hard to get the subject to stand out in such a setting.', '2006-02-18 20:23:48.000000', NULL, 1),
(2161985, 294148, 30982, '<td valign="top">Nice action capture!</td>', 'Nice action capture!', '2006-02-18 20:24:36.000000', NULL, 1),
(2161986, 294658, 30982, '<td valign="top">I''m not seeing "hope" in this expression - almost pain or sadness.</td>', 'I''m not seeing "hope" in this expression - almost pain or sadness.', '2006-02-18 20:26:25.000000', NULL, 1),
(2161987, 295546, 30982, '<td valign="top">Very elaborate costumes!  And nice to see "faith" apart from traditional Christian imagery.</td>', 'Very elaborate costumes!  And nice to see "faith" apart from traditional Christian imagery.', '2006-02-18 20:27:15.000000', NULL, 1),
(2161988, 294109, 30982, '<td valign="top">The single bird does form a focal point, but a very small one.</td>', 'The single bird does form a focal point, but a very small one.', '2006-02-18 20:28:26.000000', NULL, 1),
(2161989, 294137, 30982, '<td valign="top">Nice use of the existing light to "frame" the watering can.</td>', 'Nice use of the existing light to "frame" the watering can.', '2006-02-18 20:28:56.000000', NULL, 1),
