(2162067, 295779, 40155, '<td valign="top">Nice tones in the background.  Crisp edges.</td>', 'Nice tones in the background.  Crisp edges.', '2006-02-18 21:13:19.000000', NULL, 1),
(2162077, 294655, 40155, '<td valign="top">Great shot.  You managed to capture the beacon and the stars.  The ripples give texture. This is Print material.</td>', 'Great shot.  You managed to capture the beacon and the stars.  The ripples give texture. This is Print material.', '2006-02-18 21:15:20.000000', NULL, 1),
