(2162107, 293863, 40155, '<td valign="top">Yes this is a great representation of Heavenly Virtures.  Good balance, great cropping, fantastic work</td>', 'Yes this is a great representation of Heavenly Virtures.  Good balance, great cropping, fantastic work', '2006-02-18 21:19:46.000000', NULL, 1),
(2162115, 295247, 40155, '<td valign="top">What a creative idea!  10.</td>', 'What a creative idea!  10.', '2006-02-18 21:21:09.000000', NULL, 1),
(2162120, 295456, 40155, '<td valign="top">Great composition.  I love the digital enhancement.  10.</td>', 'Great composition.  I love the digital enhancement.  10.', '2006-02-18 21:22:08.000000', NULL, 1),
(2162130, 295901, 40155, '<td valign="top">Nice job.  The shot could use a slight rotate to the right. The flowers create the contrast in colour and in social atmosphere. 9.</td>', 'Nice job.  The shot could use a slight rotate to the right. The flowers create the contrast in colour and in social atmosphere. 9.', '2006-02-18 21:24:22.000000', NULL, 1),
(2162135, 295311, 40155, '<td valign="top">Hummm, I guess...</td>', 'Hummm, I guess...', '2006-02-18 21:25:04.000000', NULL, 1),
