(2162154, 295183, 40155, '<td valign="top">Great job.  It does seem the principal of one person combined with the splendor of Creation is a winning combination.  I will remember this next time.</td>', 'Great job.  It does seem the principal of one person combined with the splendor of Creation is a winning combination.  I will remember this next time.', '2006-02-18 21:28:08.000000', NULL, 1),
(2162158, 293727, 40155, '<td valign="top">I love the richness of the mohagany doors and the purity of the white habit.  9.</td>', 'I love the richness of the mohagany doors and the purity of the white habit.  9.', '2006-02-18 21:29:08.000000', NULL, 1),
(2162166, 295600, 40155, '<td valign="top">Bright, beautiful and busy...the tone of the photo is lost.  otherwise a nice shot with great colour and good framing.</td>', 'Bright, beautiful and busy...the tone of the photo is lost.  otherwise a nice shot with great colour and good framing.', '2006-02-18 21:30:12.000000', NULL, 1),
(2162172, 294655, 48228, '<td valign="top">This is so calm, clear and good.....I JUST LOVE it so much.....it DEFINATELY has the "WOW" factor for sure.....Deserves a "10" from me.....</td>', 'This is so calm, clear and good.....I JUST LOVE it so much.....it DEFINATELY has the "WOW" factor for sure.....Deserves a "10" from me.....', '2006-02-18 21:31:22.000000', NULL, 1),
(2162176, 295328, 40155, '<td valign="top">I suspect the use of Neat Image was slightly abused.  Otherwise a great idea.</td>', 'I suspect the use of Neat Image was slightly abused.  Otherwise a great idea.', '2006-02-18 21:32:13.000000', NULL, 1),
(2162184, 295529, 40155, '<td valign="top">Faith is a popular model.  I love the use of the colour blue against the silhouettes.</td>', 'Faith is a popular model.  I love the use of the colour blue against the silhouettes.', '2006-02-18 21:33:37.000000', NULL, 1),
