(2163182, 295600, 24454, '<td valign="top">Is that the San Antonio Riverwalk?   Its a beautiful photo!  I love it!!!</td>', 'Is that the San Antonio Riverwalk?   Its a beautiful photo!  I love it!!!', '2006-02-19 11:46:57.000000', NULL, 1),
(2163197, 295578, 40580, '<td valign="top">I don''t like the lighting or the crop.  The bed is a little distracting too.  Good idea and subject tho.</td>', 'I don''t like the lighting or the crop.  The bed is a little distracting too.  Good idea and subject tho.', '2006-02-19 12:05:46.000000', NULL, 1),
(2163424, 295868, 43410, '<td valign="top">great shot.  love the DOF you used here.  nice job.  10</td>', 'great shot.  love the DOF you used here.  nice job.  10', '2006-02-19 14:26:25.000000', NULL, 1),
(2163442, 294481, 23855, '<td valign="top">Very good capture. I love the depth of field here, and I also love how you chose to position the angel in the frame. The overcast conditions and the hint of snow really provide a nice tone for the image as well. The exposure is a little blown out towards the top of the sky gradiant, and I would have liked to have seen it a little later in the day. However, it is still a great capture. Good luck and good shooting.<br/> <br/>-Matt.</td>', 'Very good capture. I love the depth of field here, and I also love how you chose to position the angel in the frame. The overcast conditions and the hint of snow really provide a nice tone for the image as well. The exposure is a little blown out towards the top of the sky gradiant, and I would have liked to have seen it a little later in the day. However, it is still a great capture. Good luck and good shooting. -Matt.', '2006-02-19 14:42:52.000000', NULL, 1),
(2163554, 295905, 15959, '<td valign="top">out of focus</td>', 'out of focus', '2006-02-19 15:55:10.000000', NULL, 1),
