(2165067, 295868, 50530, '<td valign="top">focus is lost here</td>', 'focus is lost here', '2006-02-20 03:41:55.000000', NULL, 1),
(2165070, 293654, 50530, '<td valign="top">great work</td>', 'great work', '2006-02-20 03:43:52.000000', NULL, 1),
(2165079, 295779, 52472, '<td valign="top">Perfect execution. But a bit cheesy for this subject... 8</td>', 'Perfect execution. But a bit cheesy for this subject... 8', '2006-02-20 03:53:02.000000', NULL, 1),
(2165174, 294655, 49581, '<td valign="top">I would have given a higher vote if you used the rule of 3rds to compose the horizon.</td>', 'I would have given a higher vote if you used the rule of 3rds to compose the horizon.', '2006-02-20 06:45:16.000000', NULL, 1),
(2165178, 295126, 49581, '<td valign="top">Looks to much like a snapshot, perhaps a lower angle would work better.</td>', 'Looks to much like a snapshot, perhaps a lower angle would work better.', '2006-02-20 06:52:59.000000', NULL, 1),
(2165183, 295846, 49581, '<td valign="top">Nice picture, perhaps if the light source was at a higher angle, the shadow would be emphised more.</td>', 'Nice picture, perhaps if the light source was at a higher angle, the shadow would be emphised more.', '2006-02-20 07:00:34.000000', NULL, 1),
(2165184, 295901, 49581, '<td valign="top">I think a tighter crop would have worked better</td>', 'I think a tighter crop would have worked better', '2006-02-20 07:01:08.000000', NULL, 1),
(2165190, 295756, 49581, '<td valign="top">Looks too much like a snapshot, even a bit of fill-flash would help.</td>', 'Looks too much like a snapshot, even a bit of fill-flash would help.', '2006-02-20 07:05:33.000000', NULL, 1),
(2165194, 295185, 49581, '<td valign="top">Great foreground, shame about the background</td>', 'Great foreground, shame about the background', '2006-02-20 07:07:51.000000', NULL, 1),
(2165635, 295738, 49480, '<td valign="top">Level your horizon...place it at either a 1/3 or 2/3 of the image (depending on if you want to accentuate the sky or the sea).  Nice concept.</td>', 'Level your horizon...place it at either a 1/3 or 2/3 of the image (depending on if you want to accentuate the sky or the sea).  Nice concept.', '2006-02-20 12:27:29.000000', NULL, 1),
(2165640, 294371, 49480, '<td valign="top">Same shot I was trying to do...it''s a little hard to see justice without the scales.</td>', 'Same shot I was trying to do...it''s a little hard to see justice without the scales.', '2006-02-20 12:28:27.000000', NULL, 1),
(2165644, 295578, 49480, '<td valign="top">Great shot.  Try and prevent the hotspots from window lighting.  Try not to crop off parts of her head (unless you''re cropping off a lot to get the face).  I actually would''ve preferred to see a closer crop over her shoulder with her hands and face only.  Smaller DOF to remove the distracting bedpost.</td>', 'Great shot.  Try and prevent the hotspots from window lighting.  Try not to crop off parts of her head (unless you''re cropping off a lot to get the face).  I actually would''ve preferred to see a closer crop over her shoulder with her hands and face only.  Smaller DOF to remove the distracting bedpost.', '2006-02-20 12:31:09.000000', NULL, 1),
(2165651, 295794, 49480, '<td valign="top">Blindfold would''ve worked better for the ''Lady Justice''.</td>', 'Blindfold would''ve worked better for the ''Lady Justice''.', '2006-02-20 12:34:17.000000', NULL, 1),
