INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(2197041, 295790, 35804, '<td valign="top">I thought I had commented on this, I was one of your 10s...I really loved the untypical bold composition...the massive amount of black and darkness just brought home the idea of faith for me...just because we don''t see something doesn''t mean it''s not there.</td>', 'I thought I had commented on this, I was one of your 10s...I really loved the untypical bold composition...the massive amount of black and darkness just brought home the idea of faith for me...just because we don''t see something doesn''t mean it''s not there.', '2006-03-02 21:28:17.000000', NULL, 0),
(2197717, 295332, 42567, '<td valign="top">Awesome picture!  Congratulations on your top 10!!</td>', 'Awesome picture!  Congratulations on your top 10!!', '2006-03-03 07:09:10.000000', NULL, 0),
(2206993, 295697, 47702, '<td valign="top">I like this shot; nice winter scene</td>', 'I like this shot; nice winter scene', '2006-03-07 10:54:38.000000', NULL, 0),
